// React 19 Action State Pattern
import { useActionState } from "react";

// Server action or async mutation
async function updateProfile(previousState, formData) {
  const name = formData.get("name");
  const res = await fetch("/api/user", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name }),
  });
  return await res.json();
}

export default function UserProfile() {
  const [state, formAction, isPending] = useActionState(updateProfile, null);

  return (
    <form action={formAction} className="space-y-4">
      <input name="name" placeholder="Full name" required disabled={isPending} />
      <button type="submit" disabled={isPending}>
        {isPending ? "Updating profile..." : "Save Profile"}
      </button>
      {state?.error && <p className="text-red-500">{state.error}</p>}
    </form>
  );
}

// app/api/courses/route.ts - Next.js Route Handler
import { NextResponse } from "next/server";

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const track = searchParams.get("track") || "all";

  // Revalidate or cached response
  return NextResponse.json(
    { success: true, timestamp: Date.now(), track },
    {
      headers: {
        "Cache-Control": "public, s-maxage=3600, stale-while-revalidate=59",
      },
    }
  );
}

